import type { Listing } from '../types';
import { makeListing } from './factory';
import overridesJson from './verified-overrides.json';

/**
 * Verified fields for the destinations that have been checked against a real
 * source. The file is generated by `.tools/apply-verification.mjs` from
 * `docs/verification/batch-*.json` — never edit it by hand, and never add a
 * value here that does not have a source URL behind it.
 *
 * A field that is `null` means the source was checked and does not state it:
 * that clears the seeded guess rather than leaving it in place. A field that is
 * absent was not part of the check.
 */
type VerifiedPatch = Partial<Listing> & { isNew?: boolean };

const table = overridesJson.overrides as unknown as Record<string, VerifiedPatch>;

export const verifiedSlugs = Object.keys(table);

export function isVerified(slug: string) {
  return Boolean(table[slug]);
}

export function applyVerified(listing: Listing): Listing {
  const patch = table[listing.slug];
  if (!patch) return listing;
  const { isNew, ...rest } = patch;
  const next: Listing = { ...listing, ...rest };
  for (const [key, value] of Object.entries(rest)) {
    if (value === null) delete (next as unknown as Record<string, unknown>)[key];
  }
  return next;
}

/** Records the research proved exist but that the catalogue did not carry. */
export function verifiedNewListings(existing: Listing[]): Listing[] {
  const have = new Set(existing.map((l) => l.slug));
  return Object.entries(table)
    .filter(([slug, patch]) => patch.isNew && !have.has(slug))
    .map(([slug, patch]) => {
      if (!patch.categoryId || !patch.areaId || !patch.name || !patch.description)
        throw new Error(`${slug} is marked isNew without category/area/name/description`);
      return applyVerified(
        makeListing({
          slug,
          categoryId: patch.categoryId,
          areaId: patch.areaId,
          name: patch.name,
          description: patch.description,
        })
      );
    });
}

export const verifiedSourceNote = overridesJson.note;
